#!/usr/bin/env python3
"""AIRTAXI_NOISE2 analysis (registration planned/AIRTAXI_NOISE2_PREREG.md). Reads out/airtaxi_noise2_*.json; writes planned/airtaxi_noise2_results_table.md."""
import json, glob, statistics as st
rows = [r for f in sorted(glob.glob('out/airtaxi_noise2_[0-9]*.json')) for r in json.load(open(f))]
def get(m, li, w, key): return [r[key] for r in rows if r['metro'] == m and r['li'] == li and r['win'] == w]
P = []
def chk(n, ok, t): P.append((n, ok, t)); print('PASS' if ok else 'FAIL', n, t)
chk('P1', all(r['popDNL65'] == 0 and r['cells65'] == 0 for r in rows), f"max off-site DNL over all runs {max(r['dnlOffsiteMax'] for r in rows):.1f} dB; cells >= 65: {sum(r['cells65'] for r in rows)}")
d16, d18 = [], []
for m in ('DFW', 'HOU'):
    for li in range(3):
        b = st.median(get(m, li, 'D12', 'dnlOffsiteMax')); d16.append(st.median(get(m, li, 'D16', 'dnlOffsiteMax')) - b); d18.append(st.median(get(m, li, 'D18', 'dnlOffsiteMax')) - b)
chk('P2', all(0.5 <= x <= 1.0 for x in d16), 'D16 - D12: ' + ', '.join(f'{x:+.2f}' for x in d16))
chk('P3', all(2.8 <= x <= 3.8 for x in d18), 'D18 - D12: ' + ', '.join(f'{x:+.2f}' for x in d18))
a, b = st.median(get('DFW', 1, 'D12', 'popN55_10')), st.median(get('HOU', 1, 'D12', 'popN55_10'))
chk('P4', 3000 <= a <= 40000 and 1000 <= b <= 25000, f'people with >= 10 loud flights, D12: DFW 24/h {a:,.0f}; Houston 12/h {b:,.0f}')
c, d = st.median(get('DFW', 2, 'D18', 'popDNL55')), st.median(get('HOU', 2, 'D18', 'popDNL55'))
chk('P5', c > 0 and d > 0, f'people at DNL >= 55, D18, top level: DFW {c:,.0f}; Houston {d:,.0f}')
npass = sum(1 for _, ok, _ in P if ok); print(f'{npass} of {len(P)} passed')
L = ['# AIRTAXI_NOISE2 results table (generated by planned/airtaxi_noise2_analyze.py)', '', f'{npass} of {len(P)} predictions passed. Runs: {len(rows)}.', ''] + [f'- {"PASS" if ok else "FAIL"} {n}: {t}' for n, ok, t in P]
L += ['', '## People under the noise (off-site cells, medians over 5 seeds)', '', '| Metro | Trips/h | Window | Peak off-site DNL (dB) | People with >= 10 loud flights | >= 50 loud flights | People at DNL >= 55 | at DNL >= 65 |', '|---|---|---|---|---|---|---|---|']
for m in ('DFW', 'HOU'):
    for li in range(3):
        T = [r['T'] for r in rows if r['metro'] == m and r['li'] == li][0]
        for w in ('D12', 'D16', 'D18'):
            L.append(f"| {m} | {T:g} | {w} | {st.median(get(m, li, w, 'dnlOffsiteMax')):.1f} | {st.median(get(m, li, w, 'popN55_10')):,.0f} | {st.median(get(m, li, w, 'popN55_50')):,.0f} | {st.median(get(m, li, w, 'popDNL55')):,.0f} | {st.median(get(m, li, w, 'popDNL65')):,.0f} |")
L += ['', 'Windows: D12 06:00-18:00 (published), D16 06:00-22:00, D18 06:00-24:00. DNL adds 10 dB for 22:00-07:00, so 06:00-07:00 already counts as night in every window.']
open('planned/airtaxi_noise2_results_table.md', 'w').write('\n'.join(L) + '\n'); print('wrote planned/airtaxi_noise2_results_table.md')
